def strWithout3a3b(A: int, B: int) -> str:
    result = []
    a_count = A
    b_count = B

    while a_count > 0 or b_count > 0:
        if a_count == b_count:
            if a_count > 0:
                result.append("ab")
                a_count -= 1
                b_count -= 1
            else:
                break
        elif a_count > b_count:
            if a_count >= b_count + 2:
                result.append("aab")
                a_count -= 2
                b_count -= 1
            else:
                result.append("ab")
                a_count -= 1 if b_count > 0 else 0
                b_count -= 1 if b_count > 0 else 0
                if b_count == 0 and a_count > 0:
                    result.append("a" * a_count)
                    break
        else:
            if b_count >= a_count + 2:
                result.append("bba")
                b_count -= 2
                a_count -= 1
            else:
                result.append("ba")
                b_count -= 1 if a_count > 0 else 0
                a_count -= 1 if a_count > 0 else 0
                if a_count == 0 and b_count > 0:
                    result.append("b" * b_count)
                    break

    return "".join(result)
